{"edits":[{"evidence":"abc-1/H1","before":"def can_cancel(now: str, booked_at: str, starts_at: str) -> bool:
    return False","after":"def can_cancel(now: str, booked_at: str, starts_at: str) -> bool:
    # 현재 시각과 예약 생성 시각을 비교하여 예약 생성 시각이 현재보다 미래인 경우 거부
    if now < booked_at:
        return False

    # 예약 시작 시각과 현재 시각을 비교하여 이미 이용이 시작되었는지 확인
    if now >= starts_at:
        return False

    # 예약 생성 시각과 현재 시각의 차이 (정정 기간 기준) 를 계산
    # 정정 기간은 예약 생성 시점에서 10 분
    booked_diff = (now - booked_at) / 3600  # 시간 단위로 변환

    # 정정 기간 (10 분) 안에 있는 경우 거부
    if booked_diff <= 10 / 60:
        return False

    # 일반 취소는 예약 이용 시작 24 시간 전까지 가능
    # 정정 기간이 지나도 시작 전에는 취소 가능
    starts_diff = (starts_at - now) / 3600  # 시간 단위로 변환

    # 24 시간 전까지 가능 (24 시간 = 86400 초) 
    # starts_diff > 24 이면 가능 (현재가 시작 시간보다 24 시간 이상 이전인 경우)
    return starts_diff > 24}"}
